entries[55369] = { ["name"] = "Titanstahlzerstörer", ["text"] = "Wirken in 25 sek.\nTools:\nSchmiedehammer\nReagenzien:\nSaronitbarren (8), Titanstahlbarren (8), Gefrorene Kugel (2)\nTitanstahlzerstörer\nWird beim Anlegen gebunden\nEinzigartig anlegbarZweihändig Streitkolben\n507 - 761 Schaden Tempo 3.40\n(186.47 Schaden pro Sekunde)\n+124 Stärke\n+105 Ausdauer\nHaltbarkeit 120 / 120\n80\nErhöht die Angriffskraft um 1843 nur in Katzen-, Bären-, Terrorbären- und Mondkingestalt.\nAnlegen: Erhöht die Trefferwertung um 54." }
entries[55370] = { ["name"] = "Titanstahlknochenzermalmer", ["text"] = "Wirken in 25 sek.\nTools:\nSchmiedehammer\nReagenzien:\nSaronitbarren (6), Titanstahlbarren (6), Gefrorene Kugel (2)\nTitanstahlknochenzermalmer\nWird beim Anlegen gebunden\nEinzigartig anlegbarWaffenhand Streitkolben\n251 - 467 Schaden Tempo 2.50\n(143.60 Schaden pro Sekunde)\n+59 Ausdauer\nHaltbarkeit 105 / 105\n80\nErhöht die Angriffskraft um 1243 nur in Katzen-, Bären-, Terrorbären- und Mondkingestalt.\nAnlegen: Erhöht die Angriffskraft um 140.\nAnlegen: Erhöht Eure Waffenkundewertung um 29." }
