entries[55974] = { ["name"] = "Siedendes Blut", ["text"] = "Sofort 15 sek. Abklingzeit\nVerursacht, dass alle Krankheitseffekte auf Zielen innerhalb von 30 Metern schmerzvoll ausbrechen und dabei 2250 bis 2750 Schaden verursachen (modifiziert durch Angriffskraft). Zwingt alle Ziele dazu, until cancelled lang den Todesritter anzugreifen." }
entries[55975] = { ["name"] = "Unheilige Raserei", ["text"] = "45 Meter Reichweite\nSofort\nVersetzt eine freundliche Einheit 8 sec lang in einen Blutrausch, erhöht ihren verursachten körperlichen Schaden um 40%, lässt sie jedoch pro Sekunde 1% ihrer maximalen Gesundheit verlieren." }
entries[55976] = { ["name"] = "Zauberabwehr", ["text"] = "Wirken in 1 sek.\nGreift in der Nähe befindliche Feinde mit einem Wirbel von Stahl an, der 6 sec lang anhält und alle 2 Sek. Waffenschaden verursacht. Verleiht dem Zaubernden zeitweilige Magie-Immunität." }
entries[55977] = { ["name"] = "Wirbelwind", ["text"] = "Sofort\nReflektiert Magie.\nVerursacht bei nahen Feinden alle 2 Sek. normalen Schaden." }
entries[55978] = { ["name"] = "Herzstoß", ["text"] = "-10 Runenmacht Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nEin brutaler Angriff, der den Feind sofort schlägt und 150% Waffenschaden plus für jede auf das Ziel wirkende Krankheit zusätzlich 615 Schaden verursacht. Ziele dieses Angriffs können 10 Sek. lang keine Hasteffekte nutzen." }
entries[55980] = { ["name"] = "Mammuttrampeln", ["text"] = "Wirken in 0.25 sek. 4 sek. Abklingzeit\nVerursacht bei Feinden innerhalb von 10 Metern 5266 to 7734 Schaden." }
entries[55981] = { ["name"] = "Mammuttrompeten", ["text"] = "40 Meter Reichweite\nSofort 10 sek. Abklingzeit\nVerspottet das Ziel, damit es Euch angreift, hat aber keinerlei Effekt, wenn das Ziel Euch bereits angreift." }
entries[55982] = { ["name"] = "Mammutansturm", ["text"] = "5 - 30 Meter ReichweiteWirken in 0.9 sek. 8 sek. Abklingzeit\nStürmt auf einen Gegner zu, fügt ihm normalen Schaden plus 2647 to 2953 zu und betäubt ihn 3 sec lang." }
entries[55983] = { ["name"] = "Zur Ruhe betten", ["text"] = "10 Meter Reichweite\nWirken in 1 sek.\nLasst Hodirs Horn erklingen, wenn Ihr bei den Überresten eines Vorfahren von Niffelem oder eines ruhelosen Frosterben steht." }
entries[55984] = { ["name"] = "Schattenblitz", ["text"] = "90 Mana 40 Meter Reichweite\nWirken in 2.5 sek.\nSchleudert einen Blitz aus dunkler Magie auf einen Gegner, verursacht Schattenschaden und erhöht 10 sec lang erlittenen Schattenschaden um 10%." }
entries[55986] = { ["name"] = "Geist eines Frostriesen beschwören" }
entries[55987] = { ["name"] = "Verschlingender Feuerball", ["text"] = "1200 Mana Unbegrenzte Reichweite\nSofort 0.5 sek. Abklingzeit\nFeuert einen verschlingenden Feuerball auf feindliche Ziele, verursacht 3063 to 3937 Schaden an allen Ghulen und 10500 to 13500 Schaden an Riesen." }
entries[55988] = { ["name"] = "Verschlingender Feuerball", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerursacht 3063 to 3937 Schaden an allen Ghulen in einem Radius von 15 Metern und 10500 to 13500 Schaden an allen Riesen in einem Radius von 15 Metern." }
